def simulate(insns, k=5):
    n = len(insns)
    if n == 0:
        return 0, 0
    stalls = 0
    for i in range(n - 1):
        cur, nxt = insns[i], insns[i + 1]
        dst = cur.get("dst", 0)
        if dst and dst in nxt.get("src", []):
            # 只有 load-use 才真的停 1 拍；ALU 结果可旁路
            if cur.get("is_load", False):
                stalls += 1
    total = k + (n - 1) + stalls
    return total, stalls

if __name__ == "__main__":
    prog = [
        {"dst": 1, "src": [2, 3], "is_load": False},   # ADD R1,R2,R3
        {"dst": 4, "src": [1, 5], "is_load": False},   # SUB R4,R1,R5  -> ALU RAW, 0 停
        {"dst": 6, "src": [4],    "is_load": True},    # LW  R6,0(R4)  -> ALU RAW, 0 停
        {"dst": 0, "src": [6, 1], "is_load": False},   # SW  0(R6),R1  -> load-use, 1 停
        {"dst": 7, "src": [6, 4], "is_load": False},
    ]
    print(simulate(prog))   # (10, 1)  -> 5 段填充 + 4 条后续 + 1 拍 load-use 停顿
